rules":{"details":["Pas de pourcentage de ressemblance.","Une étiquette laissée de côté n'est pas un désaccord ; répondre n'est jamais obligatoire."],"how_to":["Place jusqu'à six étiquettes dans les trois zones.","Ajoute un détail facultatif sur l'une d'elles (80 caractères).","Révélez, puis touchez une étiquette de l'autre pour en savoir plus."],"objective":"La carte de tes goûts : souvent, parfois, pas mon truc.","privacy":"Tes réponses restent cachées jusqu'à ce que vous ayez confirmé tous les deux. Tu peux toujours passer.","step_texts":{"ask":{"confirm":"Demander","hint":"Une question facultative.","prompt":"Touche une étiquette de {name}.","title":"En savoir plus"},"map":{"confirm":"Valider ma carte","hint":"Touche une étiquette, puis une zone.","prompt":"Range tes goûts.","title":"Ta carte"},"reply":{"confirm":"Répondre","hint":"Facultatif.","prompt":"Si tu en as envie.","title":"Répondre"}}}},{"config":{"after":[],"draw":{"fixed":{"papers":[{"hex":"#F17868","name":"papier corail"},{"hex":"#A9D9C2","name":"papier menthe"},{"hex":"#F4D57A","name":"papier jaune"},{"hex":"#91BDD4","name":"papier bleu"},{"hex":"#C7B5E5","name":"papier lilas"},{"hex":"#D9B48F","name":"papier kraft"}],"ribbons":[{"hex":"#663C59","name":"ruban prune"},{"hex":"#FFF5E8","name":"ruban crème"},{"hex":"#F17868","name":"ruban rayé"},{"hex":"#C9A227","name":"ruban doré"}]},"lists":[{"bank":"gift_prompts","count":3,"key":"prompts"},{"bank":"objects","count":12,"key":"objects"}]},"engine":"rounds","mechanic":"gift_box","rounds":1,"steps":[{"key":"gift","kind":"gift"}]},"id":"N2-122","rules":{"details":["Aucun gage, aucun achat réel.","Rien n'est envoyé avant ta confirmation ; aucun message n'est écrit à ta place."],"how_to":["Choisis un papier et un ruban.","Remplis les trois compartiments (chacun peut rester vide).","Quand vous avez validé tous les deux, chacun ouvre la boîte de l'autre, un compartiment à la fois."],"objective":"La boîte à surprises : un objet symbolique, un mot et un petit dessin pour l'autre.","privacy":"Tes réponses restent cachées jusqu'à ce que vous ayez confirmé tous les deux. Tu peux toujours passer.","step_texts":{"gift":{"confirm":"Fermer la boîte","hint":"Un compartiment peut rester vide.","prompt":"Prépare une surprise pour {name}.","title":"Ta boîte"}}}},{"config":{"after":[{"key":"last1","kind":"line","who":"seat1"},{"after":"last1","key":"last2","kind":"line","who":"seat2"},{"after":"last2","key":"last3","kind":"line","who":"seat1"},{"after":"last3","key":"last4","kind":"line","who":"seat2"}],"draw":{"lists":[{"bank":"zine_themes","count":1,"key":"themes"},{"bank":"stickers","count":null,"key":"stickers"}]},"engine":"rounds","mechanic":"zine","rounds":1,"steps":[{"key":"page","kind":"page"},{"key":"cover","kind":"cover_pick","params":{"from":"page"}}]},"id":"N2-123","rules":{"details":["Ta page reste privée jusqu'à la validation ; l'autre ne peut ni la modifier ni la publier.","Enregistrement dans l'Espace seulement si vous le choisissez tous les deux."],"how_to":["Compose ta page : texte (200 caractères), gommettes et crayon.","Propose un détail de ta page pour la couverture.","Après la révélation, la dernière page se remplit en alternant deux interventions chacun."],"objective":"Le mini-fanzine à deux : une couverture commune, une page chacun, une dernière page ensemble.","privacy":"Tes réponses restent cachées jusqu'à ce que vous ayez confirmé tous les deux. Tu peux toujours passer.","step_texts":{"cover":{"confirm":"Proposer","hint":"Une gommette posée ou une courte phrase.","prompt":"Quel détail de ta page proposes-tu ?","title":"Pour la couverture"},"last":{"confirm":"Ajouter","hint":"80 caractères.","prompt":"À ton tour d'ajouter une ligne ou une gommette.","title":"Dernière page"},"page":{"confirm":"Valider ma page","hint":"Texte, gommettes et dessin : au moins un des trois.","prompt":"Thème : {theme}","title":"Ta page"}}}}]$n$::jsonb) as x(id text, rules jsonb, config jsonb)),
changed as (
  select s.* from src s join public.games g on g.id = s.id
  where not exists (select 1 from public.game_versions v where v.game_id = s.id and v.version = g.current_version
                    and v.rules = s.rules and v.config = s.config)),
ins as (
  insert into public.game_versions (game_id, version, rules, config, published_at)
  select c.id, coalesce((select max(version) from public.game_versions where game_id = c.id), 0) + 1, c.rules, c.config, now()
  from changed c returning game_id, version),
up as (update public.games g set current_version = ins.version from ins where g.id = ins.game_id returning true as inserted)
insert into public.catalogue_imports (content_version, report)
select $n$2.1.0$n$, jsonb_build_object('partie', $n$1/3$n$, 'section', $n$versions de règles$n$,
  'ajouts', count(*) filter (where inserted), 'mises_a_jour', count(*) filter (where not inserted)) from up;

-- La démo « Portrait en cinq mots » est remplacée par N2-005 (décision 3a) ; ses parties restent dans l'historique.
update public.games set status = 'archived' where id = 'portrait-en-cinq-mots' and status <> 'archived';
update public.game_categories set status = 'archived' where id = 'se-decouvrir' and status <> 'archived';
insert into public.game_favorites (user_id, game_id, created_at)
  select user_id, 'N2-005', created_at from public.game_favorites where game_id = 'portrait-en-cinq-mots'
  on conflict do nothing;
